async function main(): Promise<number> {
  const argv = process.argv.slice(2);
  if (argv.includes("--help") || argv.includes("-h")) {
    console.log(usage());
    return 0;
  }

  const options = parseArgs(argv);
  const runId = timestampRunId("dev-integrations");
  const bundleDir = makeBundlePaths(options.bundleDir, runId);
  const stepLogPath = path.join(bundleDir, "step-log.ndjson");
  const startedAt = new Date().toISOString();
  const runStartMs = Date.now();
  const steps: StepRecord[] = [];

  let preflightReportPath: string | null = null;
  let evidence: EvidenceManifest | null = null;

  appendStepLog(stepLogPath, { level: "info", stepId: "bundle", event: "run.started", runId });

  appendStepLog(stepLogPath, { level: "info", stepId: "preflight", event: "step.started" });
  const preflightStarted = Date.now();
  const preflight = runPreflightCheck({
    repoRoot: REPO_ROOT,
    namespace: options.namespace,
    bundleDir
  });
  preflightReportPath = preflight.reportPath ? toPosixRelative(bundleDir, preflight.reportPath) : null;
  const preflightLog = formatPreflightReport(preflight.report);
  fs.writeFileSync(path.join(bundleDir, "evidence", "logs", "preflight.log"), preflightLog, "utf8");
  recordStep(stepLogPath, steps, {
    id: "preflight",
    status: preflight.report.passed ? "passed" : "failed",
    durationMs: Date.now() - preflightStarted,
    errorMessage: preflight.report.passed ? null : "dev-integrations preflight failed"
  });

  if (preflight.report.passed) {
    appendStepLog(stepLogPath, { level: "info", stepId: "playwright", event: "step.started" });
    const playwrightStarted = Date.now();

    try {
      await waitForTiltUiResourcesQuiescent({
        resourceNames: ["app-v3", "app-v3-workers"]
      });

      const invocation = buildDevIntegrationsRunnerInvocation(options, bundleDir);
      const result = runCommand({
        command: invocation.command,
        commandArgs: invocation.commandArgs,
        env: invocation.env,
        workdir: invocation.workdir,
        logPath: path.join(bundleDir, "evidence", "logs", "playwright.log")
      });

      recordStep(stepLogPath, steps, {
        id: "playwright",
        status: result.exitCode === 0 ? "passed" : "failed",
        durationMs: Date.now() - playwrightStarted,
        errorMessage:
          result.exitCode === 0
            ? null
            : `playwright:dev-integrations:run exited with code ${result.exitCode}`
      });
    } catch (error) {
      recordStep(stepLogPath, steps, {
        id: "playwright",
        status: "failed",
        durationMs: Date.now() - playwrightStarted,
        errorMessage: error instanceof Error ? error.message : String(error)
      });
    }
  } else {
    recordStep(stepLogPath, steps, {
      id: "playwright",
      status: "skipped",
      durationMs: 0,
      errorMessage: "skipped because preflight failed"
    });
  }

  appendStepLog(stepLogPath, { level: "info", stepId: "evidence", event: "step.started" });
  const evidenceStarted = Date.now();
  evidence = await collectEvidence({
    bundleDir,
    runId,
    scenarioId: `dev-integrations:${options.profile}`,
    runStartMs,
    logAdapter: createKubectlLogAdapter(),
    smtp4dev: createSmtp4devAdapter(options.smtp4devUrl),
    jaeger: createJaegerAdapter(options.jaegerUrl),
    services: ["app-v3", "app-v3-workers"],
    stepArtifactHints: {
      preflight: preflightReportPath ? [preflightReportPath] : [],
      playwright: ["ui-artifacts"]
    }
  });
  fs.writeFileSync(
    path.join(bundleDir, "evidence", "logs", "evidence-collector.log"),
    `${formatEvidenceManifest(evidence)}\n`,
    "utf8"
  );
  recordStep(stepLogPath, steps, {
    id: "evidence",
    status: "passed",
    durationMs: Date.now() - evidenceStarted,
    errorMessage: null
  });

