    fn insert(&mut self, collection: CollectionId, cached: CachedMarkdownTemplate) {
        if self.capacity == 0 {
            return;
        }

        self.entries.insert(collection.clone(), cached);
        self.touch(&collection);
        self.evict_to_capacity();
    }

