function defaultCliCommandRunner(command: string, commandArgs: string[]): {
  exitCode: number;
  stdout: string;
  stderr: string;
} {
  const result = spawnSync(command, commandArgs, {
    cwd: REPO_ROOT,
    encoding: "utf8"
  });

  return {
    exitCode: result.status ?? 1,
    stdout: result.stdout ?? "",
    stderr: result.stderr ?? ""
  };
}

async function waitForTiltUiResourcesQuiescent(args: {
  resourceNames: string[];
  timeoutMs?: number;
  pollMs?: number;
  commandRunner?: typeof defaultCliCommandRunner;
}): Promise<TiltUiResourceStatus[]> {
  const timeoutMs = args.timeoutMs ?? 180_000;
  const pollMs = args.pollMs ?? 5_000;
  const commandRunner = args.commandRunner ?? defaultCliCommandRunner;
  const deadline = Date.now() + timeoutMs;
  let lastStatuses: TiltUiResourceStatus[] = [];

  while (Date.now() < deadline) {
    lastStatuses = args.resourceNames.map((resourceName) => {
      const result = commandRunner("tilt", ["get", "uiresource", resourceName, "-o", "json"]);
      if (result.exitCode !== 0) {
        const detail = result.stderr.trim() || result.stdout.trim() || `tilt exited with code ${result.exitCode}`;
        throw new Error(`Unable to inspect Tilt resource '${resourceName}': ${detail}`);
      }

      return parseTiltUiResourceStatus(
        resourceName,
        JSON.parse(result.stdout) as {
          status?: {
            queued?: boolean;
            runtimeStatus?: string;
            updateStatus?: string;
            currentBuild?: unknown;
          };
        }
      );
    });

    if (lastStatuses.every(isTiltUiResourceQuiescent)) {
      return lastStatuses;
    }

    await new Promise((resolve) => setTimeout(resolve, pollMs));
  }

  const summary = lastStatuses
    .map((status) =>
      `${status.resourceName}[runtime=${status.runtimeStatus}, update=${status.updateStatus}, queued=${status.queued}, currentBuild=${status.hasCurrentBuild}]`
    )
    .join("; ");
  throw new Error(`Tilt resources not quiescent within ${timeoutMs}ms: ${summary}`);
}

function usage(): string {
  return [
    "Usage: pnpm -C scripts proof:dev-integrations [options]",
    "",
    "Options:",
    `  --bundle-dir, -o <dir>  Output root for proof bundles (default: ${DEFAULT_BUNDLE_ROOT})`,
    "  --profile <name>        smoke | standard | scale (default: scale)",
    "  --namespace <name>      Kubernetes namespace (default: default)",
    "  --base-url <url>        Override DEV_INTEGRATIONS_BASE_URL for the Playwright runner",
    "  --grep <pattern>        Forward a grep filter to the Playwright runner",
    `  --smtp4dev-url <url>    smtp4dev evidence source (default: ${DEFAULT_SMTP4DEV_URL})`,
    `  --jaeger-url <url>      Jaeger evidence source (default: ${DEFAULT_JAEGER_URL})`,
    "  --help                  Show usage"
  ].join("\n");
}

function resolveBaseUrl(
  options: Pick<RunnerOptions, "baseUrl">,
  env: NodeJS.ProcessEnv = process.env
): string {
  return options.baseUrl ?? env["DEV_INTEGRATIONS_BASE_URL"] ?? "https://app.local.gd:11443";
}

function ensureDir(target: string): void {
  fs.mkdirSync(target, { recursive: true });
}

export function timestampRunId(prefix: string): string {
  const stamp = new Date().toISOString().replace(/[-:]/g, "").slice(0, 15) + "Z";
  return `${prefix}-${stamp}-${crypto.randomBytes(3).toString("hex")}`;
}

function toPosixRelative(bundleDir: string, targetPath: string): string {
  return path.relative(bundleDir, targetPath).split(path.sep).join("/");
}

export function makeBundlePaths(root: string, runId: string): string {
  const bundleRoot = path.isAbsolute(root) ? root : path.resolve(REPO_ROOT, root);
  const bundleDir = path.join(bundleRoot, runId);

  ensureDir(bundleDir);
  ensureDir(path.join(bundleDir, "transcripts"));
  ensureDir(path.join(bundleDir, "exports"));
  ensureDir(path.join(bundleDir, "ui-artifacts"));
  ensureDir(path.join(bundleDir, "evidence", "logs"));
  ensureDir(path.join(bundleDir, "observability"));

  return bundleDir;
}

