export function determineRunStatus(args: {
  steps: StepRecord[];
  reconciliation: ReconciliationReport;
  validationResults?: ValidationResult[];
}): "passed" | "failed" {
  if (args.steps.some((step) => step.status === "failed")) {
    return "failed";
  }

  if (args.reconciliation.summary.failed > 0) {
    return "failed";
  }

  if (args.validationResults && args.validationResults.some((result) => !result.ok)) {
    return "failed";
  }

  return "passed";
}

