}

function runCommand(args: {
  command: string;
  commandArgs: string[];
  env: NodeJS.ProcessEnv;
  workdir: string;
  logPath: string;
}): { exitCode: number; durationMs: number } {
  const startedAt = Date.now();
  const result = spawnSync(args.command, args.commandArgs, {
    cwd: args.workdir,
    env: args.env,
    encoding: "utf8",
    maxBuffer: 32 * 1024 * 1024
  });
  const durationMs = Date.now() - startedAt;

  const combinedOutput = [
    result.stdout?.trimEnd(),
    result.stderr?.trimEnd()
  ]
    .filter((entry) => entry && entry.length > 0)
    .join("\n");
  fs.writeFileSync(args.logPath, `${sanitizeLoggedCommandOutput(combinedOutput)}\n`, "utf8");

  return {
    exitCode: result.status ?? 1,
    durationMs
  };
}

function recordStep(logPath: string, steps: StepRecord[], step: StepRecord): void {
  steps.push(step);
  appendStepLog(logPath, {
    level: step.status === "failed" ? "error" : "info",
    stepId: step.id,
    event: step.status === "failed" ? "step.failed" : "step.completed",
    durationMs: step.durationMs,
    message: step.errorMessage
  });
}

