const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const REPO_ROOT = path.resolve(__dirname, "..");
const DEFAULT_BUNDLE_ROOT = "proof-bundles";
const DEFAULT_SMTP4DEV_URL = "http://localhost:2526";
const DEFAULT_JAEGER_URL = "http://localhost:16686";
const GRAPHILE_NODE_CANDIDATES = [
  "/home/linuxbrew/.linuxbrew/opt/node@22/bin/node",
  "/opt/homebrew/opt/node@22/bin/node"
];

export interface GraphileToolchain {
  nodeBinary: string;
  yarnCli: string;
}

export interface RunnerInvocation {
  command: string;
  commandArgs: string[];
  env: NodeJS.ProcessEnv;
  workdir: string;
}

export interface TiltUiResourceStatus {
  resourceName: string;
  queued: boolean;
  runtimeStatus: string;
  updateStatus: string;
  hasCurrentBuild: boolean;
}

export function resolveGraphileToolchain(repoRoot = REPO_ROOT): GraphileToolchain {
  const yarnCli = path.join(
    repoRoot,
    "interfaces",
    "graphile",
    ".yarn",
    "releases",
    "yarn-4.12.0.cjs"
  );
  const nodeBinary =
    GRAPHILE_NODE_CANDIDATES.find((candidate) => fs.existsSync(candidate)) ?? process.execPath;

  return { nodeBinary, yarnCli };
}

export function parseArgs(argv: string[]): RunnerOptions {
  const options: RunnerOptions = {
    bundleDir: DEFAULT_BUNDLE_ROOT,
    profile: "scale",
    namespace: "default",
    smtp4devUrl: DEFAULT_SMTP4DEV_URL,
    jaegerUrl: DEFAULT_JAEGER_URL
  };

  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index];
    if (arg === "--" || arg === "--help" || arg === "-h") {
      continue;
    }
    if ((arg === "--bundle-dir" || arg === "-o") && argv[index + 1]) {
      options.bundleDir = argv[index + 1]!;
      index += 1;
      continue;
    }
    if (arg === "--profile" && argv[index + 1]) {
      const candidate = argv[index + 1];
      if (candidate === "smoke" || candidate === "standard" || candidate === "scale") {
        options.profile = candidate;
      } else {
        throw new Error(`Unsupported --profile value: ${candidate}`);
      }
      index += 1;
      continue;
    }
    if (arg === "--namespace" && argv[index + 1]) {
      options.namespace = argv[index + 1]!;
      index += 1;
      continue;
    }
    if (arg === "--base-url" && argv[index + 1]) {
      options.baseUrl = argv[index + 1]!;
      index += 1;
      continue;
    }
    if (arg === "--grep" && argv[index + 1]) {
      options.grep = argv[index + 1]!;
      index += 1;
      continue;
    }
    if (arg === "--smtp4dev-url" && argv[index + 1]) {
      options.smtp4devUrl = argv[index + 1]!;
      index += 1;
      continue;
    }
    if (arg === "--jaeger-url" && argv[index + 1]) {
      options.jaegerUrl = argv[index + 1]!;
      index += 1;
      continue;
    }

    throw new Error(`Unknown argument: ${arg}`);
  }

  return options;
}

export function buildDevIntegrationsRunnerInvocation(
  options: Pick<RunnerOptions, "profile" | "baseUrl" | "grep">,
  bundleDir: string,
  repoRoot = REPO_ROOT,
  toolchain = resolveGraphileToolchain(repoRoot),
  envOverrides: NodeJS.ProcessEnv = process.env
): RunnerInvocation {
  const env = { ...envOverrides };
  delete env["npm_config_user_agent"];

  const commandArgs = [toolchain.yarnCli, "playwright:dev-integrations:run"];
  if (options.grep) {
    commandArgs.push("--grep", options.grep);
  }

  return {
    command: toolchain.nodeBinary,
    commandArgs,
    env: {
      ...env,
      PATH: `${path.dirname(toolchain.nodeBinary)}${path.delimiter}${env["PATH"] ?? ""}`,
      PROOF_BUNDLE_DIR: bundleDir,
      DEV_INTEGRATIONS_PROOF_PROFILE: options.profile,
      DEV_INTEGRATIONS_BASE_URL: resolveBaseUrl(options, env)
    },
    workdir: path.join(repoRoot, "interfaces", "graphile", "e2e")
  };
}

export function sanitizeLoggedCommandOutput(output: string): string {
  return output
    .replace(/(\bauthorization:\s*bearer\s+)[^\s\x1b]+/gi, "$1[REDACTED]")
    .replace(/("Authorization"\s*:\s*")(?!\[REDACTED\])[^"]+(")/g, '$1[REDACTED]$2')
    .replace(/^(\s*-\s*cookie:\s*).+$/gim, "$1[REDACTED]")
    .replace(/^(\s*-\s*set-cookie:\s*).+$/gim, "$1[REDACTED]")
    .replace(/^(\s*-\s*x-api-token:\s*).+$/gim, "$1[REDACTED]");
}

export function parseTiltUiResourceStatus(
  resourceName: string,
  raw: {
    status?: {
      queued?: boolean;
      runtimeStatus?: string;
      updateStatus?: string;
      currentBuild?: unknown;
    };
  }
): TiltUiResourceStatus {
  return {
    resourceName,
    queued: raw.status?.queued ?? false,
    runtimeStatus: raw.status?.runtimeStatus ?? "unknown",
    updateStatus: raw.status?.updateStatus ?? "unknown",
    hasCurrentBuild: raw.status?.currentBuild != null
  };
}

export function isTiltUiResourceQuiescent(status: TiltUiResourceStatus): boolean {
  return (
    !status.queued &&
    !status.hasCurrentBuild &&
    (status.runtimeStatus === "ok" || status.runtimeStatus === "not_applicable") &&
    (status.updateStatus === "ok" || status.updateStatus === "not_applicable")
  );
}

function defaultCliCommandRunner(command: string, commandArgs: string[]): {
  exitCode: number;
  stdout: string;
  stderr: string;
} {
  const result = spawnSync(command, commandArgs, {
    cwd: REPO_ROOT,
    encoding: "utf8"
  });

  return {
    exitCode: result.status ?? 1,
    stdout: result.stdout ?? "",
    stderr: result.stderr ?? ""
  };

