function ensureDir(target: string): void {
  fs.mkdirSync(target, { recursive: true });
}

export function timestampRunId(prefix: string): string {
  const stamp = new Date().toISOString().replace(/[-:]/g, "").slice(0, 15) + "Z";
  return `${prefix}-${stamp}-${crypto.randomBytes(3).toString("hex")}`;
}

function toPosixRelative(bundleDir: string, targetPath: string): string {
  return path.relative(bundleDir, targetPath).split(path.sep).join("/");
}

export function makeBundlePaths(root: string, runId: string): string {
  const bundleRoot = path.isAbsolute(root) ? root : path.resolve(REPO_ROOT, root);
  const bundleDir = path.join(bundleRoot, runId);

  ensureDir(bundleDir);
  ensureDir(path.join(bundleDir, "transcripts"));
  ensureDir(path.join(bundleDir, "exports"));
  ensureDir(path.join(bundleDir, "ui-artifacts"));
  ensureDir(path.join(bundleDir, "evidence", "logs"));
  ensureDir(path.join(bundleDir, "observability"));

  return bundleDir;
}

function appendStepLog(logPath: string, entry: Record<string, unknown>): void {
  fs.appendFileSync(
    logPath,
    `${JSON.stringify({ ts: new Date().toISOString(), ...entry })}\n`,
    "utf8"
  );
}

function collectFilesRecursive(dir: string, pattern: RegExp): string[] {
  if (!fs.existsSync(dir)) {
    return [];
  }

  const files: string[] = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      files.push(...collectFilesRecursive(fullPath, pattern));
      continue;
    }
    if (pattern.test(entry.name)) {
      files.push(fullPath);
    }
  }

  return files.sort();
}

export function collectBundleArtifacts(bundleDir: string): BundleArtifacts {
  const rel = (fullPath: string) => toPosixRelative(bundleDir, fullPath);

  return {
    transcripts: collectFilesRecursive(
      path.join(bundleDir, "transcripts"),
      /\.(http|graphql)\.json$/i
    ).map(rel),
    exports: collectFilesRecursive(path.join(bundleDir, "exports"), /\.jsonl$/i).map(rel),
    screenshots: collectFilesRecursive(path.join(bundleDir, "ui-artifacts"), /\.(png|jpe?g)$/i).map(rel),
    traces: collectFilesRecursive(path.join(bundleDir, "ui-artifacts"), /\.(zip|mp4|webm)$/i).map(rel),
    uiMetadata: collectFilesRecursive(path.join(bundleDir, "ui-artifacts"), /\.meta\.json$/i).map(rel),
    observability: collectFilesRecursive(
      path.join(bundleDir, "observability"),
      /\.json$/i
    ).map(rel)
  };
}

function stepFailed(steps: StepRecord[], stepId: string): boolean {
  return steps.some((step) => step.id === stepId && step.status === "failed");
}

