function validationFailures(results: ValidationResult[]): string[] {
  return results.filter((result) => !result.ok).map((result) => {
    const detail = result.detail ? `: ${result.detail}` : "";
    return `${result.label}${detail}`;
  });
}

function formatAssertionValue(value: unknown): string {
  if (typeof value === "string") {
    return value;
  }

  try {
    return JSON.stringify(value);
  } catch {
    return String(value);
  }
}

export function reconciliationFailures(report: ReconciliationReport): string[] {
  return report.assertions
    .filter((assertion) => !assertion.passed)
    .map((assertion) => {
      const detail = assertion.errorMessage
        ? `: ${assertion.errorMessage}`
        : ` (expected ${formatAssertionValue(assertion.expected)}, actual ${formatAssertionValue(assertion.actual)})`;
      return `${assertion.id}: ${assertion.description}${detail}`;
    });
}

export function determineRunStatus(args: {
  steps: StepRecord[];
  reconciliation: ReconciliationReport;
  validationResults?: ValidationResult[];
}): "passed" | "failed" {
  if (args.steps.some((step) => step.status === "failed")) {
    return "failed";
  }

  if (args.reconciliation.summary.failed > 0) {
    return "failed";
  }

  if (args.validationResults && args.validationResults.some((result) => !result.ok)) {
    return "failed";
  }

  return "passed";
}

