/// Efficiency ratios: observed performance / hardware ceiling.
#[derive(Debug, Serialize)]
struct EfficiencyReport {
    wal_append_vs_seq_write: f64,
    fsync_vs_raw_fsync: f64,
    materialize_vs_parquet_write: f64,
    scan_vs_parquet_read: f64,
}

/// V2 I/O efficiency ratios per ADR-043: end-to-end pipeline MB/s / fio ceiling.
///
/// All ratios use the 128K block size as the reference since observed WAL flush
/// sizes are 2-4 MB (well into the large-block regime).
#[derive(Debug, Serialize)]
struct IoEfficiencyReport {
    /// E2E Kafka produce MB/s / fio seq_write @ 128K.
    produce_io_efficiency: f64,
    /// Delta materialize MB/s / fio seq_write @ 128K.
    materialize_io_efficiency: f64,
    /// Query full-scan MB/s / fio seq_read @ 128K.
    scan_io_efficiency: f64,
    /// WAL + materialize concurrent MB/s / fio seq_write @ 128K.
    combined_io_efficiency: f64,
    /// The fio baseline file hash used to compute these ratios.
    io_baseline_hash: String,
    /// The reference block size used (always "128k").
    reference_block_size: String,
}

/// Physics baseline data loaded from cached JSON.
#[derive(Debug, serde::Deserialize)]
struct PhysicsBaselineFile {
    baselines: PhysicsBaselines,
}

#[derive(Debug, serde::Deserialize)]
struct PhysicsBaselines {
    seq_write_mb_per_sec: f64,
    fsync_p50_us: u64,
    parquet_write_mb_per_sec: f64,
    parquet_read_mb_per_sec: f64,
}



