    use niflheim_wal::WalConfig;

    let write_mode = match stage {
        Stage::WalAppendTracked => WriteMode::Tracked,
        Stage::WalAppendDurable => WriteMode::Durable,
        Stage::DeltaMaterialize => {
            unreachable!("delta materialize uses its dedicated stage runner")
        }
    };

    let total_records = params.records;
    let payload_size = params.payload_size;
    let batch_size = params.batch_size;

    if !json_output {
        eprintln!("=== Niflheim Isolated WAL Stage Benchmark ===");
        eprintln!("Stage:        {stage}");
        eprintln!("Write mode:   {write_mode:?}");
        eprintln!("Records:      {}", format_number(total_records));
        eprintln!("Payload:      {} bytes", format_number(payload_size as u64));
        eprintln!("Batch size:   {} records", format_number(batch_size as u64));
        eprintln!();
    }

    // Build a standalone WAL runtime in a temp directory.
    let tempdir = tempfile::TempDir::new().context("create WAL benchmark temp dir")?;
    let wal_root = tempdir.path().join("wal");
    std::fs::create_dir_all(&wal_root).context("create WAL root")?;

    let node_id: [u8; 16] = *uuid::Uuid::new_v4().as_bytes();
    let wal_config = WalConfig::default();

    if !json_output {
        eprintln!("Building WAL runtime...");
    }
    let wal_runtime = build_local_wal_runtime(node_id, &wal_root, wal_config, 1, vec![])
        .await
        .context("build local WAL runtime")?;
    let wal_writer = wal_runtime.manager;

    if !json_output {
        eprintln!("WAL runtime ready");
        eprintln!();
    }

    // Fixed partition key for benchmark entries.
    let partition = PartitionKey::new(1, 1, 20_454); // arbitrary fixed date

    // Pre-generate a payload template (reused across all entries).
    let payload_template = Bytes::from(vec![b'x'; payload_size]);

    // Write entries in batches, measuring per-batch latency.
    let num_batches = (total_records as usize).div_ceil(batch_size);
    let mut latency = LatencyCollector::new();
    let mut total_bytes: u64 = 0;

    if !json_output {
        eprintln!("Writing {} batches...", format_number(num_batches as u64));
    }

    let bench_start = Instant::now();
    let mut offset: u64 = 0;

    for batch_idx in 0..num_batches {
        let batch_start_record = batch_idx * batch_size;
        let batch_end_record = ((batch_idx + 1) * batch_size).min(total_records as usize);
        let batch_count = batch_end_record - batch_start_record;

        let entries: Vec<WalEntry> = (0..batch_count)
            .map(|_| {
                let entry = WalEntry::new(
                    partition,
                    1_705_276_800_000, // fixed timestamp for reproducibility
                    payload_template.clone(),
                    offset,
                );
                offset += 1;
                entry
            })
            .collect();

        let wire_bytes: u64 = entries.iter().map(|e| e.payload.len() as u64).sum();
        total_bytes += wire_bytes;

        let batch_start = Instant::now();
        wal_writer
            .append_entries(&entries, write_mode)
            .await
            .with_context(|| format!("WAL append batch {batch_idx}"))?;
        let batch_us = batch_start.elapsed().as_micros() as u64;

        latency.record(batch_us);

        if !json_output && (batch_idx + 1) % 100 == 0 {
            let progress = (batch_idx + 1) as f64 / num_batches as f64 * 100.0;
            eprintln!("  {progress:.0}% ({}/{num_batches} batches)", batch_idx + 1);
        }
    }

    let bench_elapsed = bench_start.elapsed().as_secs_f64();
    let records_per_sec = total_records as f64 / bench_elapsed;
    let mb_per_sec = total_bytes as f64 / (1024.0 * 1024.0) / bench_elapsed;
    let p50 = latency.percentile(50.0);
    let p95 = latency.percentile(95.0);
    let p99 = latency.percentile(99.0);

    if !json_output {
        eprintln!();
        eprintln!("=== Results ===");
        eprintln!(
            "  Throughput: {} records/sec ({:.1} MB/sec)",
            format_rate(records_per_sec),
            mb_per_sec,
        );
        eprintln!(
            "  Latency p50: {:.1}ms  p95: {:.1}ms  p99: {:.1}ms",
            p50 as f64 / 1000.0,
            p95 as f64 / 1000.0,
            p99 as f64 / 1000.0,
        );
        eprintln!("  Duration: {bench_elapsed:.2}s");
        eprintln!(
            "  Total bytes: {}",
            format_mb(total_bytes as f64 / (1024.0 * 1024.0))
        );
    }

    // I/O efficiency against fio baseline (same approach as full pipeline).
    let io_efficiency = load_io_baseline().and_then(|baseline| {
        let seq_write_128k = baseline
            .sequential_write
            .get("128k")
            .map(|b| b.bandwidth_mib_sec)?;
        if seq_write_128k <= 0.0 {
            return None;
        }
        Some(IoEfficiencyReport {
            produce_io_efficiency: mb_per_sec / seq_write_128k,
            materialize_io_efficiency: 0.0,
            scan_io_efficiency: 0.0,
            combined_io_efficiency: mb_per_sec / seq_write_128k,
            io_baseline_hash: baseline.identity.hash,
            reference_block_size: "128k".to_string(),
        })
    });

    if json_output {
        let report = WalStageJsonReport {
            stage: stage.to_string(),
            records: total_records,
            payload_bytes: payload_size,
            batch_size,
            writer_tuning,
            wal_append: WalAppendReport {
                records_per_sec,
                mb_per_sec,
                latency_p50_us: p50,
                latency_p95_us: p95,
                latency_p99_us: p99,
                duration_secs: bench_elapsed,
                total_bytes,
            },
            io_efficiency,
        };
        let json = serde_json::to_string_pretty(&report).expect("serialize WAL stage report");
        #[allow(clippy::print_stdout)]
        {
            println!("{json}");
        }
    }


