//! Append, flush, and discard paths for `WalManager`.

use crate::{HotTierWriter, WalChunk};
use anyhow::Result;
use niflheim_core::{WalEntry, WriteMode};
use niflheim_core::{stage_timing, wal_observability};
use niflheim_telemetry::{histogram, metric_names};
use opentelemetry::trace::TraceContextExt;
use std::time::Instant;
use tracing::Instrument;
use tracing_opentelemetry::OpenTelemetrySpanExt;

use super::helpers::write_mode_str;
use super::{AppendResult, WalChunkRegistrar, WalManager};
use crate::ChunkMetadata;

const DEFAULT_TRANSACTION_SCOPE: &str = "__default__";

impl<WH, R> WalManager<WH, R>
where
    WH: HotTierWriter + 'static,
    R: WalChunkRegistrar + 'static,
{
    /// Append owned entries to the WAL (avoids per-entry cloning).
    ///
    /// Behavior depends on the write mode:
    /// - `FireAndForget`: Returns after hot-tier append (no sync).
    /// - `Tracked`: Returns after hot-tier flush to OS page cache (no fsync).
    /// - `Durable`: Returns after hot-tier flush and durable-store persist.
    ///
    /// # Errors
    ///
    /// Returns an error if writing or registration fails.
    #[allow(
        clippy::too_many_lines,          // WAL append owned path kept together for clarity.
        clippy::cast_possible_truncation, // as_micros() u128→u64: WAL ops will never hit 2^64 µs.
        clippy::single_match_else,        // match on WriteMode is clearer than nested if-let.
    )]
    #[tracing::instrument(
        name = "niflheim.wal.append",
        skip(self, entries),
        fields(node_id = %self.node_id_hex, entry_count = entries.len(), mode = ?mode)
    )]
    pub async fn append_entries_owned(
        &self,
        entries: Vec<WalEntry>,
        mode: WriteMode,
    ) -> Result<AppendResult> {
        if entries.is_empty() {
            return Ok(AppendResult {
                entries_appended: 0,
                hot_chunks_written: vec![],
                durable_chunks_written: vec![],
            });
        }

        let entry_count = entries.len();
        let start = Instant::now();

        let chunk_seq = self.next_chunk_seq();
        let chunk = WalChunk::new(self.node_id, chunk_seq, entries)?
            .with_trace_id(current_trace_id(&tracing::Span::current()));
        let encoded_chunk = self.encode_chunk(&chunk)?;

        // All modes append to the in-memory segment buffer first.
        // - FireAndForget: returns after buffer append (data may not yet be on disk).
        // - Tracked: flushes the buffer to the OS page cache (survives process
        //   crash) but does NOT fsync (power-loss may lose data). This is the
        //   key decoupling that removes fsync from the produce hot path.
        // - Durable: syncs the hot tier and waits for cold-tier persistence
        //   to satisfy the durability guarantee.
        match mode {
            WriteMode::Tracked => {
                let write_start = Instant::now();
                let hot_metadata = self
                    .hot_writer
                    .write_hot_chunk_flushed(encoded_chunk)
                    .await?;
                let tracked_elapsed = write_start.elapsed();
                stage_timing::WAL_WRITE.record_us(tracked_elapsed.as_micros() as u64);
                wal_observability::global_registry().record_write(
                    u64::try_from(entry_count).unwrap_or(u64::MAX),
                    hot_metadata.size_bytes,
                    tracked_elapsed,
                );
                self.track_hot_chunk(
                    &hot_metadata,
                    chunk.offset_start,
                    chunk.offset_end(),
                    chunk.chunk_id(),
                )
                .await;

                histogram!(
                    metric_names::ingestion::ACK_LATENCY,
                    start.elapsed().as_secs_f64(),
                    "node_id" => self.node_id_hex.clone(),
                    "mode" => write_mode_str(mode)
                );

                Ok(AppendResult {
                    entries_appended: entry_count,
                    hot_chunks_written: vec![hot_metadata],
                    durable_chunks_written: vec![],
                })
            }
            WriteMode::Durable => {
                let encoded_bytes = encoded_chunk.bytes.clone();
                let write_start = Instant::now();
                let hot_metadata = self.write_hot_chunk(encoded_chunk).await?;
                stage_timing::WAL_WRITE.record_us(write_start.elapsed().as_micros() as u64);
                wal_observability::global_registry().record_write(
                    u64::try_from(entry_count).unwrap_or(u64::MAX),
                    hot_metadata.size_bytes,
                    write_start.elapsed(),
                );
                self.track_hot_chunk(
                    &hot_metadata,
                    chunk.offset_start,
                    chunk.offset_end(),
                    chunk.chunk_id(),
                )
                .await;
                let hot_chunks_written = vec![hot_metadata.clone()];
                let flush_start = Instant::now();
                self.hot_writer
                    .sync_hot()
                    .instrument(tracing::debug_span!(
                        "niflheim.wal.fsync",
                        node_id = %self.node_id_hex,
                        mode = ?WriteMode::Durable
                    ))
                    .await?;
                stage_timing::WAL_FSYNC.record_us(flush_start.elapsed().as_micros() as u64);
                wal_observability::global_registry().record_fsync(flush_start.elapsed());
                let durable_chunk = self
                    .write_and_register_chunk_with_bytes(chunk, hot_metadata, Some(encoded_bytes))
                    .await?;
                Ok(AppendResult {
                    entries_appended: entry_count,
                    hot_chunks_written,
                    durable_chunks_written: vec![durable_chunk],
                })
            }
            WriteMode::FireAndForget => {
                let write_start = Instant::now();
                let hot_metadata = self.write_hot_chunk(encoded_chunk).await?;
                stage_timing::WAL_WRITE.record_us(write_start.elapsed().as_micros() as u64);
                wal_observability::global_registry().record_write(
                    u64::try_from(entry_count).unwrap_or(u64::MAX),
                    hot_metadata.size_bytes,
                    write_start.elapsed(),
                );
