    /// Record a hot chunk write in the segment offset index and detect segment rolls.
    pub(super) async fn track_hot_chunk(
        &self,
        hot: &HotChunkMetadata,
        offset_start: u64,
        offset_end: u64,
        chunk_id: String,
    ) {
        let Some(segment_seq) = extract_segment_seq(&hot.path) else {
            return;
        };

        self.segment_index
            .record_chunk(
                segment_seq,
                hot.path.clone(),
                offset_start,
                offset_end,
                chunk_id.clone(),
            )
            .await;
        wal_observability::global_registry().record_hot_chunk(&chunk_id, hot.size_bytes);

        let mut last = self.last_segment_seq.lock().await;
        if let Some(prev_seq) = *last
            && prev_seq != segment_seq
        {
            self.segment_index.seal_segment(prev_seq).await;

            // Trigger coalesced cold write for the sealed segment (non-blocking).
            let snapshot = self.segment_index.snapshot().await;
            if let Some(sealed_range) = snapshot.get(&prev_seq) {
                let store = self.durable_store.clone();
                let path = sealed_range.path.clone();
                let chunk_ids = sealed_range.chunk_ids.clone();
                tokio::spawn(async move {
                    match store
                        .persist_sealed_segment(prev_seq, &path, &chunk_ids)
                        .await
                    {
                        Ok(_meta) => {
                            // Clean up per-chunk cold files superseded by the
                            // coalesced segment.
                            if let Err(e) = store.cleanup_coalesced_chunks(&chunk_ids).await {
                                tracing::warn!(
                                    segment_seq = prev_seq,
                                    error = %e,
                                    "failed to clean up per-chunk cold files"
