                            }
                        }
                        Err(e) => {
                            tracing::warn!(
                                segment_seq = prev_seq,
                                error = %e,
                                "failed to coalesce sealed segment to cold tier"
                            );
                        }
                    }
                });
            }
        }
        *last = Some(segment_seq);
