//! Types and traits for the WAL manager.

use crate::{ChunkMetadata, HotChunkMetadata, WalEntry};
use anyhow::Result;
use std::collections::HashMap;
use std::time::Duration;

/// Policy for handling corrupt WAL segments during recovery.
///
/// By default the WAL reader fails on the first checksum mismatch
/// (`Strict`).  `SkipCorrupt` quarantines the offending segment and
/// continues recovery with the remaining data — trading completeness
/// for availability.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum RecoveryPolicy {
    /// Fail immediately on checksum mismatch (default).
    #[default]
    Strict,
    /// Log an error, move the corrupt segment to a `.quarantine/`
    /// subdirectory, and continue recovery with remaining segments.
    SkipCorrupt,
}

/// Configuration for WAL segment thresholds.
#[derive(Clone, Debug)]
pub struct WalConfig {
    /// Maximum segment size in bytes before forced roll.
    pub max_buffer_bytes: usize,
    /// Minimum buffered bytes to accumulate before forcing a tracked flush.
    pub min_flush_bytes: usize,
    /// Maximum segment age before forced roll for synchronous modes.
    pub max_buffer_age: Duration,
    /// Maximum time to wait for additional tracked writes before forcing a
    /// tracked flush.
    pub max_flush_delay: Duration,
    /// Maximum segment age before forced roll for async modes.
    ///
    /// Set to `Duration::ZERO` to disable time-based flush for async modes.
    pub max_buffer_age_async: Duration,
    /// Timeout for durable (cold-tier) chunk writes.
    ///
    /// If a cold-tier persist exceeds this duration the write is aborted and
    /// an error is returned rather than blocking indefinitely.
    /// `Duration::ZERO` disables the timeout.
    pub durable_write_timeout: Duration,
    /// Maximum interval to coalesce hot-tier fsyncs for durable writes.
    ///
    /// `Duration::ZERO` disables batching and fsyncs every sync request.
    pub durable_sync_interval: Duration,
}

impl Default for WalConfig {
    fn default() -> Self {
        Self {
            max_buffer_bytes: 100 * 1024 * 1024, // 100 MB
            min_flush_bytes: 64 * 1024,
            max_buffer_age: Duration::from_millis(100),
            max_flush_delay: Duration::from_micros(500),
            max_buffer_age_async: Duration::from_secs(60),
            durable_write_timeout: Duration::from_secs(30),
            durable_sync_interval: Duration::from_millis(50),
        }
    }
