#[allow(
    clippy::unused_async,
    reason = "S3 cold-writer construction awaits only when the optional `s3` feature is enabled"
)]
async fn create_cold_writer_from_storage_config(
    node_id: NodeId,
    storage_config: &StorageConfig,
) -> Result<Option<(Arc<dyn WalChunkStore>, Arc<dyn ObjectStore>)>> {
    match storage_config.cold_tier_backend {
        ColdTierBackend::Local => Ok(None),
        ColdTierBackend::S3 => {
            #[cfg(feature = "s3")]
            {
                let mut s3_config = S3Config::new(&storage_config.s3_bucket)
                    .with_region(&storage_config.aws_region)
                    .with_force_path_style(storage_config.s3_force_path_style);
                if let Some(endpoint) = &storage_config.s3_endpoint_url {
                    s3_config = s3_config.with_endpoint(endpoint);
                }
                let store = Arc::new(S3ObjectStore::new(node_id, s3_config).await?);
                let cold_writer: Arc<dyn WalChunkStore> = store.clone();
                let durable_object_store: Arc<dyn ObjectStore> = store;
                Ok(Some((cold_writer, durable_object_store)))
            }
            #[cfg(not(feature = "s3"))]
            {
                let _ = node_id;
                anyhow::bail!(
                    "cold_tier_backend=s3 requires the niflheim-object-store `s3` feature"
                );
            }
        }
    }
}

